namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
            Steps = "1. Mix dry ingredients together.\n2. Whisk eggs and milk, then combine with dry mix.\n3. Heat a non-stick pan over medium heat.\n4. Pour batter and cook until bubbles form, then flip.\n5. Serve with maple syrup."
        },
        new Recipe
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
            Steps = "1. Toast the bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread on toast and sprinkle with red pepper flakes."
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
            Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g Pecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Fry pancetta until crispy.\n3. Mix egg yolks with grated cheese and pepper.\n4. Toss hot pasta with pancetta, then stir in egg mixture off heat.\n5. Serve immediately."
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Stir Fry", Category = "Dinner",
            Ingredients = "500g chicken breast\n2 bell peppers\n1 broccoli head\n3 tbsp soy sauce\n1 tbsp sesame oil\nGarlic and ginger",
            Steps = "1. Slice chicken and vegetables.\n2. Heat sesame oil in a wok over high heat.\n3. Cook chicken until browned, then remove.\n4. Stir fry vegetables for 3 minutes.\n5. Return chicken, add soy sauce and garlic-ginger paste.\n6. Serve over rice."
        },
        new Recipe
        {
            Id = 5, Title = "Caesar Salad", Category = "Lunch",
            Ingredients = "1 romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
            Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved Parmesan.\n4. Add grilled chicken if desired."
        },
        new Recipe
        {
            Id = 6, Title = "Tomato Basil Soup", Category = "Lunch",
            Ingredients = "6 ripe tomatoes\n1 onion\n3 cloves garlic\nFresh basil\nVegetable broth\nCream",
            Steps = "1. Roast tomatoes and garlic at 200°C for 20 minutes.\n2. Sauté onion until soft.\n3. Add roasted tomatoes, broth, and simmer 15 minutes.\n4. Blend until smooth, stir in cream and basil."
        },
        new Recipe
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "2.25 cups flour\n1 cup butter\n0.75 cup sugar\n0.75 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
            Steps = "1. Cream butter and sugars together.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheet.\n6. Bake at 175°C for 10-12 minutes."
        },
        new Recipe
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Ingredients = "6 egg yolks\n500g mascarpone\n300ml strong espresso\n2 tbsp coffee liqueur\nLadyfinger biscuits\nCocoa powder",
            Steps = "1. Whisk egg yolks with sugar until pale.\n2. Fold in mascarpone until smooth.\n3. Mix espresso with coffee liqueur.\n4. Dip ladyfingers briefly in coffee mixture.\n5. Layer biscuits and cream in a dish.\n6. Refrigerate 4 hours, dust with cocoa before serving."
        }
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

