arguments.file_text:
@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes with our community.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in Categories)
    {
        <div class="col-md-3 mb-4">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category</h5>
                    <a href="/recipes/@category.ToLower()" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories { get; set; } = Array.Empty<string>();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>
<p><a href="/">← Back to categories</a></p>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = Array.Empty<RecipeShare.Models.Recipe>();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: <a href="/recipes/@Recipe.Category.ToLower()">@Recipe.Category</a></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && char.IsDigit(text[0]) && text[1] == '.')
                text = text[2..].TrimStart();
            else if (text.Length > 3 && char.IsDigit(text[0]) && char.IsDigit(text[1]) && text[2] == '.')
                text = text[3..].TrimStart();
            <li>@text</li>
        }
    </ol>

    <h3>Rating</h3>
    <StarRating RecipeId="Recipe.Id" />
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @if (Submitted)
    {
        <p class="text-success">Thanks for rating! You gave @SubmittedStars star(s).</p>
    }

    <div>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= HoveredStar ? "highlighted" : "") @(star <= CurrentRating ? "rated" : "")"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => HoveredStar = star"
                  @onmouseout="() => HoveredStar = 0"
                  style="cursor:pointer; font-size:1.8rem;">
                @(star <= (HoveredStar > 0 ? HoveredStar : CurrentRating) ? "★" : "☆")
            </span>
        }
    </div>

    @if (AverageRating > 0)
    {
        <p class="text-muted mt-2">Average: @AverageRating.ToString("F1") ⭐ (@TotalRatings ratings)</p>
    }
    else
    {
        <p class="text-muted mt-2">Be the first to rate this recipe!</p>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private int HoveredStar { get; set; }
    private int CurrentRating { get; set; }
    private bool Submitted { get; set; }
    private int SubmittedStars { get; set; }
    private double AverageRating { get; set; }
    private int TotalRatings { get; set; }

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        CurrentRating = stars;
        SubmittedStars = stars;
        Submitted = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe != null)
        {
            AverageRating = recipe.AverageRating;
            TotalRatings = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@SubmittedTitle</strong>" has been added.
        <a href="/recipe/@SubmittedId">View it here</a>.
    </div>
}

<EditForm Model="FormModel" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="FormModel.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => FormModel.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="FormModel.Category" class="form-control">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => FormModel.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="FormModel.Ingredients" class="form-control" rows="5"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => FormModel.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="FormModel.Steps" class="form-control" rows="5"
                       placeholder="1. Preheat oven to 180°C&#10;2. Mix ingredients&#10;3. Bake for 30 minutes" />
        <ValidationMessage For="() => FormModel.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel FormModel { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private string SubmittedTitle { get; set; } = string.Empty;
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        var recipe = new RecipeShare.Models.Recipe
        {
            Title = FormModel.Title,
            Category = FormModel.Category,
            Ingredients = FormModel.Ingredients,
            Steps = FormModel.Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedTitle = recipe.Title;
        SubmittedId = recipe.Id;
        SubmitSuccess = true;
        FormModel = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

